float noise(vec2 p, float freq ){
	float unit = 1./freq;
	vec2 ij = floor(p/unit);
	vec2 xy = mod(p,unit)/unit;
	//xy = .5*(1.-cos(PI/1.*xy));
	float a = rand((ij+vec2(0.,0.)))/1.;
	float b = rand((ij+vec2(1.,0.)))/1.;
	float c = rand((ij+vec2(0.,1.)))/1.;
	float d = rand((ij+vec2(1.,1.)))/1.;
	float x1 = mix(a, b, xy.x);
	float x2 = mix(c, d, xy.x);
	return mix(x1, x2, xy.y);
}


