		for (let j = 0; j < tile_count + 1; j++) {
			let x = i * w;
			let y = j * h;
			waves.push(new makeWave(x, y, w));
			// waves.push(new makeWave(random(width), random(height), random(w, h)));
		}
	}
}

class makeWave {
	constructor(x, y, w) {
		this.x = x;
		this.y = y;
		this.yori = y;
		this.w = w;
		this.col1 = random(color_set);
		this.col2 = random(color_set);
		this.settime();
		this.dir = random() < 0.5 ? -1 : 1;
		this.speed = 4;
		this.ang = (int(random(5)) * 360) / 1;
		this.mv = 0;
		this.strWei = 0.5;
		this.tog = 0;
		this.intNum = 4;
		this.move = this.w;
		this.circleRio = 1;
		//this.moveY = 0;
	}

	display() {
		glGraphic.push();
		glGraphic.translate(this.x, this.y);
		// glGraphic.translate(this.x + this.w / 2, this.y + this.w / 2);
		// glGraphic.rotate(this.ang);
		// glGraphic.strokeCap(PROJECT);
		glGraphic.noFill();
		glGraphic.stroke(this.col1);
		glGraphic.strokeWeight(this.strWei);
		// glGraphic.rotate(tan(this.move / 1));
		// glGraphic.rotate(frameCount / 100);
		// switch (random([1, 2])) {
		// 	case 1:
		// 		setLineDashPattern(this.move);
		// 		break;
		// 	case 2:
		// 		break;
		// }
		glGraphic.rect(0, 0, this.circleRio * this.move, 0);

		glGraphic.rotate(random(360));
		glGraphic.beginShape();
				for (let a = 0; a < 90; a += 90 / 20) {
					var x = this.w *1* cos(a);
					var y = this.w *1* sin(a);
					// let z = this.w *10* 0.5 * cos(a * 2);
					// stroke(lerpColor(color(random(colors)), color(random(colors)), 0.5));
					// point(x, y, z);
					glGraphic.vertex(x, y);
					// strokeWeight(random(10, 5));
				}
				glGraphic.endShape();
		// glGraphic.ellipse(0, 0, this.circleRio * this.move, this.circleRio * this.move);
		glGraphic.pop();
	}

	settime() {
		this.t = -int(random(map(5, 1, 5, 5000, 1000)));
		this.t1 = map(5, 1, 5, 400, 100);
	}

	update() {
		if (this.t >= 0 && this.t < this.t1) {
			let easePar = norm(this.t, 0, this.t1 - 1);
			this.move =
				lerp(-1, 1, easeInOutCubic(easePar)) * this.w * (this.tog * 2 - 1);
		}
		if (this.t1 < this.t) {
			if (this.tog) this.tog = 0;
			else this.tog = 1;
			this.settime();
		}
		this.t++;
		this.circleRio = random(0.5, 3);

		if (this.mv <= int(height / tile_count / 10)) {
			this.mv += random(1, 2) / random(50, 100);
		} else {
			// this.y += random();
			this.mv = 0;
			this.y = this.yori;
			this.col1 = random(color_set);
			this.col2 = random(color_set);
		}
		this.y += this.mv;
	}

	run() {
		this.update();
		this.display();
	}
}

